A.source:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /o5-user-token/n00000000000000000000000000000000/cases/{document} {
      allow read, write: if false;
    }
    match /o5-user-token/n00000000000000000000000000000000/cases/owned-a {
      allow get: if request.auth != null && request.auth.uid == resource.data.ownerUid;
    }
    match /o5-user-token/n00000000000000000000000000000000/cases/owned-b {
      allow get: if request.auth != null && request.auth.uid == resource.data.ownerUid;
    }
    match /o5-user-token/n00000000000000000000000000000000/cases/public-open {
      allow get: if request.auth == null;
    }
    match /o5-user-token/n00000000000000000000000000000000/cases/claim-gated {
      allow get: if request.auth != null && request.auth.token.o5role == 'editor';
    }
    match /o5-user-token/n00000000000000000000000000000000/cases/tenant-gated {
      allow get: if request.auth != null && request.auth.token.firebase.tenant == 'o5-user-token-tenant';
    }
    match /o5-user-token/n00000000000000000000000000000000/cases/exists-guarded {
      allow get: if request.auth != null && exists(/databases/$(database)/documents/o5-user-token/n00000000000000000000000000000000/cases/exists-guard-present);
    }
    match /o5-user-token/n00000000000000000000000000000000/cases/exists-guarded-missing {
      allow get: if request.auth != null && exists(/databases/$(database)/documents/o5-user-token/n00000000000000000000000000000000/cases/exists-guard-absent);
    }
    match /o5-user-token/n00000000000000000000000000000000/cases/get-guarded {
      allow get: if request.auth != null && get(/databases/$(database)/documents/o5-user-token/n00000000000000000000000000000000/cases/owned-a).data.ownerUid == request.auth.uid;
    }
    match /o5-user-token/n00000000000000000000000000000000/cases/getafter-target {
      allow create: if request.auth != null && getAfter(/databases/$(database)/documents/o5-user-token/n00000000000000000000000000000000/cases/getafter-guard).data.ownerUid == request.auth.uid;
    }
    match /o5-user-token/n00000000000000000000000000000000/cases/getafter-control-target {
      allow create: if request.auth != null && getAfter(/databases/$(database)/documents/o5-user-token/n00000000000000000000000000000000/cases/getafter-control-guard).data.ownerUid == request.auth.uid;
    }
    match /o5-user-token/n00000000000000000000000000000000/cases/getafter-guard {
      allow create: if request.auth != null && request.resource.data.ownerUid == request.auth.uid;
    }
    match /o5-user-token/n00000000000000000000000000000000/cases/multiwrite-x {
      allow get, update: if request.auth != null && request.auth.uid == resource.data.ownerUid;
    }
    match /o5-user-token/n00000000000000000000000000000000/cases/multiwrite-y {
      allow create: if false;
    }
  }
}

